package com.bananalab.lite;
import android.content.Context;import android.graphics.Canvas;import org.json.*;import java.io.*;import java.util.*;
/** Prepares only the current take, bounding scene/bitmap memory for long series. */
final class SeriesExporter{
 static void write(Context c,JSONArray rows,boolean three,File output,Motion motion,VideoExporter.Monitor monitor)throws Exception{List<SceneDraft> drafts=new ArrayList<>();int total=0;boolean sound=false;for(int i=0;i<rows.length();i++){SceneDraft d=SceneDraft.read(rows.getJSONObject(i).toString());SceneConsistency.require(d);drafts.add(d);total+=SceneTiming.frames(d);sound|=d.sound;}if(total==0||total>SceneTiming.MAX_SERIES_SECONDS*VideoExporter.FPS)throw new IOException("La serie debe durar hasta300 segundos.");final int count=total;final Scene[] prepared={null};final int[] take={-1};VideoExporter.Frames frames=(canvas,side,index,n)->{int at=0;for(int i=0;i<drafts.size();i++){int length=SceneTiming.frames(drafts.get(i));if(index<at+length){try{if(take[0]!=i){prepared[0]=BananaRender.prepare(c,drafts.get(i),three);take[0]=i;}prepared[0].draw(canvas,side,motion,(index-at)/(float)Math.max(1,length-1));return;}catch(Exception e){throw new IllegalStateException("No pude preparar una toma: "+e.getMessage(),e);}}at+=length;}};
  if(!sound){VideoExporter.writeFrames(output,frames,count,monitor);return;}File video=File.createTempFile("series-v-",".mp4",output.getParentFile()),audio=File.createTempFile("series-a-",".mp4",output.getParentFile());try{VideoExporter.writeFrames(video,frames,count,monitor);if(monitor.cancelled())throw new IOException("Cancelado");short[] pcm=new short[count*Soundtrack.RATE/VideoExporter.FPS];int offset=0;for(SceneDraft d:drafts){int length=SceneTiming.frames(d)*Soundtrack.RATE/VideoExporter.FPS;if(d.sound){short[] part=Soundtrack.pcm(d,SceneTiming.frames(d));System.arraycopy(part,0,pcm,offset,Math.min(length,part.length));}offset+=length;}Soundtrack.writeAac(audio,pcm);Soundtrack.mux(video,audio,output);}finally{video.delete();audio.delete();}
 }
}
